try{
 $dir=dirname(__DIR__).'/.rm-agenda';if(!is_dir($dir)&&!mkdir($dir,0700,true))throw new RuntimeException();
 $db=new PDO('sqlite:'.$dir.'/demo.sqlite');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->exec('PRAGMA busy_timeout=5000');
 $db->exec('CREATE TABLE IF NOT EXISTS services(owner TEXT,sector TEXT,id INTEGER,name TEXT,minutes INTEGER,cents INTEGER,PRIMARY KEY(owner,sector,id)); CREATE TABLE IF NOT EXISTS bookings(id INTEGER PRIMARY KEY AUTOINCREMENT,owner TEXT,sector TEXT,client TEXT,service_name TEXT,start INTEGER,end INTEGER,cents INTEGER,status TEXT,created INTEGER); CREATE TABLE IF NOT EXISTS visits(owner TEXT PRIMARY KEY,touched INTEGER)');
