 foreach($expired as $old){run($db,'DELETE FROM booking_moves WHERE booking_id IN (SELECT id FROM bookings WHERE owner=?)',[$old]);run($db,'DELETE FROM booking_clients WHERE booking_id IN (SELECT id FROM bookings WHERE owner=?)',[$old]);run($db,'DELETE FROM clients WHERE owner=?',[$old]);run($db,'DELETE FROM services WHERE owner=?',[$old]);run($db,'DELETE FROM bookings WHERE owner=?',[$old]);run($db,'DELETE FROM visits WHERE owner=?',[$old]);}
 run($db,'INSERT OR REPLACE INTO visits VALUES(?,?)',[$owner,time()]);
 foreach($defaults as $i=>$s)run($db,'INSERT OR IGNORE INTO services VALUES(?,?,?,?,?,?)',[$owner,$sector,$i+1,...$s]);
