 if(run($db,'SELECT COUNT(*) FROM clients WHERE owner=? AND sector=? AND email=?',[$owner,$sector,$email])->fetchColumn())throw new RuntimeException('Este correo ya está registrado. Elige al cliente en Nueva cita.');
 if(run($db,'SELECT COUNT(*) FROM clients WHERE owner=?',[$owner])->fetchColumn()>=100)throw new RuntimeException('Has alcanzado las 100 fichas de prueba de esta sesión.');
 run($db,'INSERT INTO clients(owner,sector,name,email,phone,created) VALUES(?,?,?,?,?,?)',[$owner,$sector,$name,$email,$phone,time()]);
 $_SESSION['selected_client_'.$sector]=(int)$db->lastInsertId();$msg='Cliente registrado. Ya puedes elegir servicio, fecha y hora para su cita.';
 }elseif($action==='price'){
 $raw=(string)($_POST['price']??'');$mins=filter_var($_POST['minutes']??null,FILTER_VALIDATE_INT);
