 $cents=(int)round((float)str_replace(',','.',$raw)*100);
 run($db,'UPDATE services SET cents=?,minutes=? WHERE owner=? AND sector=? AND id=?',[$cents,$mins,$owner,$sector,(int)($_POST['service']??0)]);$msg='Tarifa actualizada. Las citas anteriores conservan su importe.';
 }elseif($action==='book'){
 $service=run($db,'SELECT * FROM services WHERE owner=? AND sector=? AND id=?',[$owner,$sector,(int)($_POST['service']??0)])->fetch(PDO::FETCH_ASSOC);
 $channel=(string)($_POST['channel']??'Web');if(!in_array($channel,['Web','Teléfono','Presencial'],true))throw new RuntimeException('Selecciona un origen de cita válido.');
 $client=run($db,'SELECT * FROM clients WHERE id=? AND owner=? AND sector=?',[(int)($_POST['client']??0),$owner,$sector])->fetch(PDO::FETCH_ASSOC);
 if(!$client||!$service)throw new RuntimeException('Primero da de alta al cliente y después selecciona un servicio.');
 $date=(string)($_POST['date']??'');$slot=(string)($_POST['slot']??'');$d=DateTimeImmutable::createFromFormat('!Y-m-d H:i',$date.' '.$slot);
 if(!$d||$d->format('Y-m-d H:i')!==$date.' '.$slot||!preg_match('/^(09|1[0-7]):(00|30)$/',$slot)||$d->format('N')>5||$d->getTimestamp()<=time()||$date>date('Y-m-d',strtotime('+90 days')))throw new RuntimeException('Elige un día laborable futuro, dentro de los próximos 90 días.');
 $start=$d->getTimestamp();$end=$start+(int)$service['minutes']*60;if($end>$d->setTime(18,0)->getTimestamp())throw new RuntimeException('El servicio debe terminar antes de las 18:00.');
 if(run($db,"SELECT COUNT(*) FROM bookings WHERE owner=? AND sector=? AND status<>'Cancelada' AND start<? AND end>?",[$owner,$sector,$end,$start])->fetchColumn())throw new RuntimeException('Ese horario ya está ocupado. Elige otro hueco.');
 if(run($db,'SELECT COUNT(*) FROM bookings WHERE owner=?',[$owner])->fetchColumn()>=100)throw new RuntimeException('Has alcanzado las 100 citas de prueba de esta sesión.');
 run($db,"INSERT INTO bookings(owner,sector,client,service_name,start,end,cents,status,created) VALUES(?,?,?,?,?,?,?,'Pendiente',?)",[$owner,$sector,$client['name'],$service['name'],$start,$end,$service['cents'],time()]);
 run($db,'INSERT INTO booking_clients(booking_id,client_id,channel) VALUES(?,?,?)',[(int)$db->lastInsertId(),$client['id'],$channel]);
