 if(!$b||!in_array($b['status'],['Pendiente','Confirmada'],true))throw new RuntimeException('Solo puedes cambiar citas pendientes o confirmadas.');
 $date=(string)($_POST['date']??'');$slot=(string)($_POST['slot']??'');$d=DateTimeImmutable::createFromFormat('!Y-m-d H:i',$date.' '.$slot);
 if(!$d||$d->format('Y-m-d H:i')!==$date.' '.$slot||!preg_match('/^(09|1[0-7]):(00|30)$/',$slot)||$d->format('N')>5||$d->getTimestamp()<=time()||$date>date('Y-m-d',strtotime('+90 days')))throw new RuntimeException('Elige un día laborable futuro dentro de los próximos 90 días.');
 $start=$d->getTimestamp();$end=$start+((int)$b['end']-(int)$b['start']);
