 if(run($db,"SELECT COUNT(*) FROM bookings WHERE owner=? AND sector=? AND id<>? AND status<>'Cancelada' AND start<? AND end>?",[$owner,$sector,$b['id'],$end,$start])->fetchColumn())throw new RuntimeException('Ese horario ya está ocupado. La cita original se mantiene sin cambios.');
 if($start===(int)$b['start'])throw new RuntimeException('Selecciona una fecha o una hora diferente.');
 run($db,'UPDATE bookings SET start=?,end=? WHERE id=? AND owner=? AND sector=?',[$start,$end,$b['id'],$owner,$sector]);
 run($db,'INSERT INTO booking_moves(booking_id,old_start,new_start,moved_at) VALUES(?,?,?,?)',[$b['id'],$b['start'],$start,time()]);
 $msg='Cita reprogramada. Se conservan el cliente, el servicio y el precio acordado.';
 }elseif($action==='status'){
 $status=$_POST['status']??'';if(!in_array($status,['Pendiente','Confirmada','Realizada','Cancelada'],true))throw new RuntimeException('Estado no válido.');
 $b=run($db,'SELECT * FROM bookings WHERE id=? AND owner=? AND sector=?',[(int)($_POST['id']??0),$owner,$sector])->fetch(PDO::FETCH_ASSOC);
 if(!$b)throw new RuntimeException('Cita no encontrada.');
 if($b['status']==='Cancelada')throw new RuntimeException('Crea una nueva cita para recuperar una reserva cancelada.');
 run($db,'UPDATE bookings SET status=? WHERE id=? AND owner=?',[$status,$b['id'],$owner]);$msg='Estado de la cita actualizado.';
 }else throw new RuntimeException('Acción no válida.');
 $db->exec('COMMIT');$_SESSION['flash']=$msg;$redirectDate=in_array($action,['book','reschedule'],true)?(string)($_POST['date']??date('Y-m-d')):(string)($_GET['agenda_date']??date('Y-m-d'));
 $redirectView=in_array($action,['book','reschedule'],true)?'day':(string)($_GET['view']??'week');
 header('Location: gestion.php?sector='.$sector.'&view='.rawurlencode($redirectView).'&agenda_date='.rawurlencode($redirectDate).'&status_filter='.rawurlencode((string)($_GET['status_filter']??'all')).'#agenda');exit;
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();else{try{$db->exec('ROLLBACK');}catch(Throwable $ignored){}}$error=$e instanceof RuntimeException?$e->getMessage():'No se ha podido guardar. Vuelve a intentarlo.';}
}
$services=run($db,'SELECT * FROM services WHERE owner=? AND sector=? ORDER BY id',[$owner,$sector])->fetchAll(PDO::FETCH_ASSOC);
$clients=run($db,'SELECT * FROM clients WHERE owner=? AND sector=? ORDER BY name',[$owner,$sector])->fetchAll(PDO::FETCH_ASSOC);
