</style></head><body><header><div><strong><?=h($brand)?></strong><br><a href="<?=h($sector)?>.html">← Volver a la web</a></div><nav aria-label="Cambiar negocio"><?php foreach($config as $key=>$c):?><a href="?sector=<?=h($key)?>" <?=$key===$sector?'aria-current="page"':''?>><?=h($c[0])?></a><?php endforeach?></nav></header><main><section class="hero"><span class="eyebrow">Gestión del negocio · Demo interactiva</span><h1>Tu agenda, bajo control.</h1><p>Reserva una cita de prueba, ajusta tus tarifas y sigue cada trabajo desde un mismo lugar.</p><nav class="quick-actions" aria-label="Accesos de gestión"><a href="#agenda">Ver agenda</a><a href="#clientes">Buscar cliente / cita telefónica</a><a href="#alta-cliente">Nuevo cliente</a><a href="#nueva-cita">Nueva cita</a></nav></section><div class="notice"><strong>Espacio de prueba personal.</strong> Utiliza únicamente datos ficticios en el alta de clientes. Los datos se guardan en el servidor y se separan por navegador mediante una cookie de sesión. Se eliminan tras 7 días de inactividad. No es una reserva real ni un panel de producción con usuario y contraseña.</div>
<?php if($msg):?><div role="status" class="success"><?=h($msg)?></div><?php endif?><?php if($error):?><div role="alert" class="error"><?=h($error)?></div><?php endif?>
<div class="stats"><div class="stat"><span class="muted">Citas activas</span><strong><?=count($active)?></strong></div><div class="stat"><span class="muted">Importe previsto</span><strong><?=money($total)?></strong></div><div class="stat"><span class="muted">Servicios</span><strong><?=count($services)?></strong></div></div><section class="card agenda" id="agenda" aria-label="Calendario de citas"><span class="eyebrow">Agenda del negocio</span><div class="calendar-toolbar"><h2>Tu calendario</h2><nav aria-label="Vista de agenda"><?php foreach(['day'=>'Día','week'=>'Semana','month'=>'Mes'] as $v=>$label):?><a href="<?=h(agendaUrl($v,$focus->format('Y-m-d')))?>" <?=$view===$v?'aria-current="page"':''?>><?=$label?></a><?php endforeach?></nav></div><div class="calendar-toolbar"><div class="calendar-controls"><a aria-label="Periodo anterior" href="<?=h(agendaUrl($view,$navBase->modify('-1 '.$step)->format('Y-m-d')))?>">← Anterior</a><a href="<?=h(agendaUrl($view,date('Y-m-d')))?>">Hoy</a><a aria-label="Periodo siguiente" href="<?=h(agendaUrl($view,$navBase->modify('+1 '.$step)->format('Y-m-d')))?>">Siguiente →</a></div><h3 id="periodTitle"><?=h($periodTitle)?></h3></div><form method="get" action="gestion.php#agenda" class="calendar-date"><input type="hidden" name="sector" value="<?=h($sector)?>"><input type="hidden" name="view" value="<?=h($view)?>"><label for="agendaDate">Ir a una fecha</label><input id="agendaDate" name="agenda_date" type="date" required value="<?=$focus->format('Y-m-d')?>" min="2000-01-01" max="2100-12-31"><label for="statusFilter">Estado de la cita</label><select id="statusFilter" name="status_filter"><?php foreach($statusOptions as $key=>$label):?><option value="<?=h($key)?>" <?=$statusFilter===$key?'selected':''?>><?=h($label)?></option><?php endforeach?></select><button>Aplicar filtros</button></form><div class="print-tools"><p class="muted">Mostrando: <?=h($statusOptions[$statusFilter])?></p><button type="button" id="printAgenda">Imprimir agenda del periodo</button><span class="muted">También puedes guardarla como PDF desde el diálogo de impresión.</span></div><p class="muted"><?=count($periodBookings)?> citas en este periodo · Horario de España peninsular · Pulsa una cita para ver sus detalles.</p>
<?php if($view==='month'): $gridStart=$rangeStart->modify('-'.((int)$rangeStart->format('N')-1).' days');?><div class="calendar-scroll" tabindex="0" aria-label="Calendario mensual, desplazable en pantallas pequeñas"><div class="month-grid"><?php foreach($weekdays as $w):?><div class="weekday"><?=h(mb_substr($w,0,3))?></div><?php endforeach?><?php for($i=0;$i<42;$i++):$d=$gridStart->modify('+'.$i.' days');$dayBookings=array_values(array_filter($filteredBookings,fn($b)=>date('Y-m-d',$b['start'])===$d->format('Y-m-d')));?><div class="month-day <?=$d->format('m')!==$focus->format('m')?'outside':''?> <?=$d->format('Y-m-d')===date('Y-m-d')?'today':''?>"><a class="day-number" aria-label="Ver día <?=$d->format('d/m/Y')?>" href="<?=h(agendaUrl('day',$d->format('Y-m-d')))?>"><?=$d->format('j')?></a><?php foreach(array_slice($dayBookings,0,3) as $b):eventTile($b);endforeach?><?php if(count($dayBookings)>3):?><a href="<?=h(agendaUrl('day',$d->format('Y-m-d')))?>">+<?=count($dayBookings)-3?> más</a><?php endif?></div><?php endfor?></div></div>
<?php elseif($view==='week'):?><div class="calendar-scroll" tabindex="0" aria-label="Calendario semanal, desplazable en pantallas pequeñas"><div class="week-grid"><?php for($i=0;$i<7;$i++):$d=$weekStart->modify('+'.$i.' days');$dayBookings=array_filter($periodBookings,fn($b)=>date('Y-m-d',$b['start'])===$d->format('Y-m-d'));?><div class="week-day <?=$d->format('Y-m-d')===date('Y-m-d')?'today':''?>"><a class="week-heading" href="<?=h(agendaUrl('day',$d->format('Y-m-d')))?>"><?=h($weekdays[$i])?><strong><?=$d->format('d/m')?></strong></a><?php foreach($dayBookings as $b):eventTile($b);endforeach?><?php if(!$dayBookings):?><p class="muted"><?=$i>4?'Cerrado':'Sin citas'?></p><?php endif?></div><?php endfor?></div></div>
<?php else:?><div class="day-view"><?php foreach($periodBookings as $b):eventTile($b);endforeach?><?php if(!$periodBookings):?><p>No hay citas para este día. <?=$focus->format('N')>5?'El negocio está cerrado los fines de semana.':'Puedes asignar una desde Nueva cita.'?></p><?php endif?></div><?php endif?><a class="agenda-details" href="#detalle-agenda">Ver detalles del periodo ↓</a></section><section class="card agenda" id="clientes" style="margin-bottom:24px"><span class="eyebrow">Atención en el negocio</span><h2>Buscar cliente y asignar cita</h2><p class="muted">¿Te llaman para reservar? Busca la ficha y pulsa «Asignar cita por teléfono». Si es su primera visita, <a href="#alta-cliente">da de alta al cliente</a>.</p><label for="clientSearch">Buscar por nombre, teléfono o correo</label><input id="clientSearch" type="search" placeholder="Escribe un nombre, teléfono o correo" autocomplete="off"><p id="searchResult" class="muted" role="status" aria-live="polite"></p><?php if(!$clients):?><p>Cuando completes el alta, la ficha aparecerá aquí.</p><?php endif?><?php foreach($clients as $c):?><div class="client-card" data-client-search="<?=h($c['name'].' '.$c['email'].' '.$c['phone'])?>"><strong><?=h($c['name'])?></strong><span class="muted">Ficha #<?=$c['id']?> · <?=h($c['email'])?> · <?=h($c['phone'])?></span><span class="tag"><?=count(array_filter($bookings,fn($b)=>(int)($b['client_id']??0)===(int)$c['id']))?> citas vinculadas</span><a class="assign-client" href="?sector=<?=h($sector)?>&amp;client=<?=$c['id']?>&amp;channel=phone#nueva-cita">Asignar cita por teléfono</a></div><?php endforeach?></section><section class="card" id="alta-cliente"><span class="eyebrow">Paso 1 · Primera visita</span><h2>Alta de cliente</h2><p class="muted">Registra una ficha una sola vez. Después podrás reservar varias citas sin volver a escribir los datos. Ejemplo: Alex Demo · alex@example.com · 000000000.</p><form method="post"><?php hidden('register')?><div class="client-fields"><div><label for="customerName">Nombre y apellidos</label><input id="customerName" name="name" required minlength="2" maxlength="120" autocomplete="off" placeholder="Alex Demo" value="<?=h(($_POST['action']??'')==='register'?($_POST['name']??''):'')?>"></div><div><label for="customerEmail">Correo electrónico</label><input id="customerEmail" name="email" type="email" required maxlength="190" autocomplete="off" placeholder="alex@example.com" value="<?=h(($_POST['action']??'')==='register'?($_POST['email']??''):'')?>"></div><div><label for="customerPhone">Teléfono</label><input id="customerPhone" name="phone" type="tel" required maxlength="25" autocomplete="off" placeholder="000000000" value="<?=h(($_POST['action']??'')==='register'?($_POST['phone']??''):'')?>"></div></div><label class="check"><input type="checkbox" name="demo_ack" value="1" required> Confirmo que estos datos son ficticios y entiendo que esta reserva es de prueba.</label><button class="register-button">Registrar cliente y continuar</button></form></section><div class="grid" style="margin-top:24px"><section class="card" id="nueva-cita"><span class="eyebrow">Paso 2 · Reserva</span><h2>Nueva cita</h2><p class="muted">Lunes a viernes · 09:00–18:00 · Una agenda por negocio</p><form method="post"><?php hidden('book')?><label for="client">Cliente registrado</label><select id="client" name="client" required><option value="">Selecciona tu ficha de cliente</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>" <?=$selected===(int)$c['id']?'selected':''?>><?=h($c['name'])?> · <?=h($c['email'])?></option><?php endforeach?></select><p class="muted"><?php if(!$clients):?>Todavía no hay clientes registrados. Completa el alta para poder reservar.<?php else:?>¿Primera visita? <a href="#alta-cliente">Dar de alta un cliente</a>.<?php endif?></p><label for="channel">¿Cómo se ha solicitado la cita?</label><select id="channel" name="channel"><option <?=$defaultChannel==='Web'?'selected':''?>>Web</option><option <?=$defaultChannel==='Teléfono'?'selected':''?>>Teléfono</option><option>Presencial</option></select><label for="service">Servicio</label><select id="service" name="service"><?php foreach($services as $s):?><option value="<?=$s['id']?>" data-minutes="<?=$s['minutes']?>" data-cents="<?=$s['cents']?>"><?=h($s['name'])?> · <?=money($s['cents'])?></option><?php endforeach?></select><div class="row"><div><label for="date">Fecha</label><input type="date" id="date" name="date" required min="<?=date('Y-m-d')?>" max="<?=date('Y-m-d',strtotime('+90 days'))?>" value="<?=date('Y-m-d',strtotime('next monday'))?>"></div><div><label for="slot">Hora disponible</label><select id="slot" name="slot" required></select></div></div><div id="quote" aria-live="polite"></div><button id="bookButton">Guardar cita de prueba</button><p class="muted"><?=$sector==='taller'?'Importes orientativos: el presupuesto final requiere valoración del taller.':'Precios de ejemplo para la demostración.'?> La tarifa queda guardada con la cita.</p></form></section><section class="card"><h2>Servicios y tarifas</h2><p class="muted">Los cambios se aplican a las nuevas citas. Duración en bloques de 30 minutos.</p><?php foreach($services as $s):?><form class="service" method="post"><?php hidden('price')?><input type="hidden" name="service" value="<?=$s['id']?>"><strong><?=h($s['name'])?></strong><div class="row"><div><label for="price<?=$s['id']?>">Precio (€)</label><input id="price<?=$s['id']?>" name="price" inputmode="decimal" value="<?=number_format($s['cents']/100,2,'.','')?>" required></div><div><label for="minutes<?=$s['id']?>">Duración (min)</label><input id="minutes<?=$s['id']?>" type="number" name="minutes" min="30" max="240" step="30" value="<?=$s['minutes']?>" required></div></div><button>Guardar tarifa de <?=h($s['name'])?></button></form><?php endforeach?></section></div><section class="card agenda" id="detalle-agenda"><h2>Detalles de las citas del periodo</h2><p class="muted"><?=h($periodTitle)?> · <a href="#agenda">Volver al calendario ↑</a></p><p class="muted">Una cita cancelada libera su horario. Las citas realizadas conservan su historial.</p><?php if(!$periodBookings):?><p>No hay citas en este periodo. Cambia de fecha en el calendario.</p><?php endif?><?php foreach($periodBookings as $b):?><article class="appointment" id="cita-<?=$b['id']?>"><div><span class="tag"><?=h($b['status'])?></span> <span class="tag">Origen: <?=h($b['channel']??'Web')?></span><h3><?=h($b['service_name'])?></h3><p><?=date('d/m/Y · H:i',$b['start'])?>–<?=date('H:i',$b['end'])?> · <?=h($b['client'])?><br><?php if($b['client_email']):?><span class="muted"><?=h($b['client_email'])?> · <?=h($b['client_phone'])?> · Ficha #<?=$b['client_id']?></span><br><?php endif?><strong><?=money($b['cents'])?></strong> · Importe guardado en la cita</p></div><?php if($b['status']!=='Cancelada'):?><form method="post"><?php hidden('status')?><input type="hidden" name="id" value="<?=$b['id']?>"><label for="status<?=$b['id']?>">Cambiar estado</label><select name="status" id="status<?=$b['id']?>"><?php foreach(['Pendiente','Confirmada','Realizada','Cancelada'] as $state):?><option <?=$b['status']===$state?'selected':''?>><?=$state?></option><?php endforeach?></select><button style="margin-top:10px">Actualizar cita #<?=$b['id']?></button></form><?php endif?><?php if(in_array($b['status'],['Pendiente','Confirmada'],true)):?><details class="reschedule"><summary>Cambiar fecha u hora de la cita #<?=$b['id']?></summary><p class="muted">Conserva el precio y la duración originales. El servidor comprueba que el nuevo horario esté libre.</p><form method="post"><?php hidden('reschedule')?><input type="hidden" name="id" value="<?=$b['id']?>"><div class="row"><div><label for="moveDate<?=$b['id']?>">Nueva fecha · cita #<?=$b['id']?></label><input id="moveDate<?=$b['id']?>" type="date" name="date" required min="<?=date('Y-m-d')?>" max="<?=date('Y-m-d',strtotime('+90 days'))?>" value="<?=date('Y-m-d',$b['start'])?>"></div><div><label for="moveTime<?=$b['id']?>">Nueva hora · cita #<?=$b['id']?></label><select id="moveTime<?=$b['id']?>" name="slot"><?php for($m=540;$m+($b['end']-$b['start'])/60<=1080;$m+=30):$t=sprintf('%02d:%02d',intdiv($m,60),$m%60);?><option <?=$t===date('H:i',$b['start'])?'selected':''?>><?=$t?></option><?php endfor?></select></div></div><button style="margin-top:12px">Guardar nuevo horario #<?=$b['id']?></button></form></details><?php endif?><?php $history=array_filter($moves,fn($m)=>(int)$m['booking_id']===(int)$b['id']);if($history):?><details class="move-history"><summary>Historial de cambios · cita #<?=$b['id']?></summary><?php foreach($history as $m):?><p class="muted"><?=date('d/m/Y H:i',$m['old_start'])?> → <?=date('d/m/Y H:i',$m['new_start'])?><br>Modificado: <?=date('d/m/Y H:i',$m['moved_at'])?></p><?php endforeach?></details><?php endif?></article><?php endforeach?></section><section class="print-agenda"><h1><?=h($brand)?> · Agenda</h1><h2><?=h($periodTitle)?></h2><p>Estado: <?=h($statusOptions[$statusFilter])?> · <?=count($periodBookings)?> citas · Horario de España peninsular</p><table><thead><tr><th>Fecha y hora</th><th>Cliente</th><th>Servicio</th><th>Estado / Origen</th><th>Importe</th></tr></thead><tbody><?php foreach($periodBookings as $b):?><tr><td><?=date('d/m/Y H:i',$b['start'])?>–<?=date('H:i',$b['end'])?></td><td><?=h($b['client'])?></td><td><?=h($b['service_name'])?></td><td><?=h($b['status'])?> / <?=h($b['channel']??'Web')?></td><td><?=money($b['cents'])?></td></tr><?php endforeach?></tbody></table><?php if(!$periodBookings):?><p>No hay citas para los filtros seleccionados.</p><?php endif?><p>Demostración con datos ficticios · Generado el <?=date('d/m/Y H:i')?></p></section><footer><a href="index.html">← Volver al portfolio</a> · Demostración funcional de Rubén Muñoz · Horario de España peninsular</footer></main><script>
const busy=<?=json_encode(array_values(array_map(fn($b)=>['date'=>date('Y-m-d',$b['start']),'start'=>(int)date('H',$b['start'])*60+(int)date('i',$b['start']),'end'=>(int)date('H',$b['end'])*60+(int)date('i',$b['end'])],$active)),JSON_HEX_TAG)?>;
const svc=document.getElementById('service'),day=document.getElementById('date'),slot=document.getElementById('slot'),quote=document.getElementById('quote');
function refresh(){const opt=svc.selectedOptions[0],mins=Number(opt.dataset.minutes),price=Number(opt.dataset.cents)/100;slot.replaceChildren();const weekday=new Date(day.value+'T12:00:00').getDay();if(weekday>0&&weekday<6)for(let m=540;m+mins<=1080;m+=30){if(busy.some(b=>b.date===day.value&&b.start<m+mins&&b.end>m))continue;const o=document.createElement('option');o.value=String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');o.textContent=o.value;slot.append(o);}document.getElementById('bookButton').disabled=!slot.options.length||!document.getElementById('client').value;quote.textContent=price.toLocaleString('es-ES',{style:'currency',currency:'EUR'})+' · '+mins+' minutos'+(!slot.options.length?' · No hay huecos disponibles para ese día.':'');}document.getElementById('client').addEventListener('change',refresh);svc.addEventListener('change',refresh);day.addEventListener('change',refresh);refresh();
const clientSearch=document.getElementById('clientSearch'),clientRows=Array.from(document.querySelectorAll('[data-client-search]'));
function normalizeSearch(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es').trim();}
clientSearch.addEventListener('input',()=>{const q=normalizeSearch(clientSearch.value);let found=0;for(const row of clientRows){const text=normalizeSearch(row.dataset.clientSearch);const match=text.includes(q)||(q.replace(/\D/g,'').length>=3&&text.replace(/\D/g,'').includes(q.replace(/\D/g,'')));row.hidden=!match;if(match)found++;}document.getElementById('searchResult').textContent=found?found+' clientes encontrados.':'No hay coincidencias. Puedes dar de alta un nuevo cliente.';});
document.getElementById('printAgenda').addEventListener('click',()=>window.print());
</script></body></html>
